"use client";

import { useEffect, useMemo, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Area, AreaChart, Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { ArrowDownRight, ArrowRight, ArrowUpRight, Bell, CalendarDays, ChartNoAxesCombined, Check, CheckCheck, ChevronDown, ChevronLeft, ChevronRight, CircleAlert, CircleHelp, Clock3, Command, Download, Ellipsis, Heart, LayoutDashboard, ListFilter, LockKeyhole, LogOut, Mail, MapPin, Menu, MessageSquare, MoreHorizontal, Plus, QrCode, Search, Settings, Shield, SlidersHorizontal, Sparkles, Sun, Moon, Upload, UserRound, Users, UserPlus, X, Church, type LucideIcon } from "lucide-react";
import { attendance, eventAttendance, eventDetails, events, members, monthly, organizers, recurringEventTemplates } from "@/mocks/data";
import { BrandLogo } from "@/components/brand-logo";
import { formatDate } from "@/lib/utils";
import type { EventItem, Member, RecurringEventTemplate } from "@/types";

type Page = "Visão geral" | "Eventos" | "Membros" | "Participantes" | "Organizadores" | "Relatórios" | "Configurações" | "Meu perfil" | "QR Code";
const navigation: { label: Page; icon: LucideIcon; group: string }[] = [
  { label: "Visão geral", icon: LayoutDashboard, group: "PRINCIPAL" },
  { label: "Eventos", icon: CalendarDays, group: "PRINCIPAL" },
  { label: "Membros", icon: Users, group: "COMUNIDADE" },
  { label: "Participantes", icon: UserPlus, group: "COMUNIDADE" },
  { label: "Organizadores", icon: Shield, group: "COMUNIDADE" },
  { label: "Relatórios", icon: ChartNoAxesCombined, group: "GESTÃO" },
];
const avatar = (seed: string) => `https://api.dicebear.com/9.x/notionists/svg?seed=${encodeURIComponent(seed)}&backgroundColor=f3e8d5,e8e9f5,d6ede8`;
const weekdayNames = ["Domingo", "Segunda-feira", "Terça-feira", "Quarta-feira", "Quinta-feira", "Sexta-feira", "Sábado"];
function localDateValue() { const date = new Date(); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`; }
function nextDateForWeekday(weekday: number) { const date = new Date(); date.setHours(12, 0, 0, 0); let offset = (weekday - date.getDay() + 7) % 7; if (!offset) offset = 7; date.setDate(date.getDate() + offset); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`; }

function IconButton({ children, label, onClick, className = "" }: { children: React.ReactNode; label: string; onClick?: () => void; className?: string }) { return <button aria-label={label} title={label} onClick={onClick} className={`icon-btn ${className}`}>{children}</button>; }
function Badge({ children, tone = "neutral", dot = false }: { children: React.ReactNode; tone?: string; dot?: boolean }) { return <span className={`badge badge-${tone}`}>{dot && <span className="badge-dot" />}{children}</span>; }
function Avatar({ name, src, size = "normal" }: { name: string; src?: string; size?: "small" | "normal" | "large" }) { return <img className={`avatar avatar-${size}`} src={src || avatar(name)} alt={name} />; }
function SectionTitle({ eyebrow, title, subtitle, action }: { eyebrow?: string; title: string; subtitle?: string; action?: React.ReactNode }) { return <div className="section-title"><div>{eyebrow && <div className="eyebrow">{eyebrow}</div>}<h1>{title}</h1>{subtitle && <p>{subtitle}</p>}</div>{action}</div>; }
function CardHead({ title, subtitle, action }: { title: string; subtitle?: string; action?: React.ReactNode }) { return <div className="card-head"><div><h3>{title}</h3>{subtitle && <p>{subtitle}</p>}</div>{action}</div>; }

type Workspace = { name: string; description: string };
const workspaces: Workspace[] = [
  { name: "Cristo Alegria GYN", description: "Missão Goiânia" },
  { name: "Cristo Alegria SP", description: "Missão São Paulo" },
  { name: "Cristo Alegria Belém", description: "Missão Belém" },
  { name: "Cristo Alegria Brasil", description: "Membros externos" },
];

const registeredParticipants: Member[] = [
  { id: 1001, name: "Pedro Augusto", phone: "(62) 99124-3344", city: "Goiânia", group: "Participante", position: "Voluntário", status: "Ativo", since: "12/04/2025", email: "pedro.augusto@email.com", avatar: avatar("Pedro Augusto"), attendance: 72, lastVisit: { date: "10/11/2026", event: "Encontro de Jovens" } },
  { id: 1002, name: "Beatriz Oliveira", phone: "(62) 99235-4455", city: "Goiânia", group: "Participante", position: "Aspirante", status: "Ativo", since: "03/08/2025", email: "beatriz.oliveira@email.com", avatar: avatar("Beatriz Oliveira"), attendance: 64, lastVisit: { date: "08/11/2026", event: "Missa da Comunidade" } },
  { id: 1003, name: "Rafael Martins", phone: "(62) 99346-5566", city: "Aparecida de Goiânia", group: "Participante", position: "Vocacionado", status: "Ativo", since: "19/01/2026", email: "rafael.martins@email.com", avatar: avatar("Rafael Martins"), attendance: 81, lastVisit: { date: "05/11/2026", event: "Grupo de Oração" } },
  { id: 1004, name: "Camila Rodrigues", phone: "(62) 99457-6677", city: "Goiânia", group: "Participante", position: "Consagrado", status: "Ativo", since: "07/06/2024", email: "camila.rodrigues@email.com", avatar: avatar("Camila Rodrigues"), attendance: 90, lastVisit: null },
];

function WorkspaceSelector({ onNotice }: { onNotice: (message: string) => void }) {
  const [active, setActive] = useState(workspaces[0]);
  const [open, setOpen] = useState(false);

  return <div className="workspace-picker" onBlur={(event) => { if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setOpen(false); }}>
    <button className="workspace-switch" type="button" aria-haspopup="listbox" aria-expanded={open} onClick={() => setOpen((value) => !value)}>
      <span className="workspace-avatar">C</span>
      <span className="workspace-copy"><strong>{active.name}</strong><small>{active.description}</small></span>
      <ChevronDown size={15} />
    </button>
    <AnimatePresence>{open && <motion.div className="workspace-menu" role="listbox" aria-label="Selecionar workspace" initial={{ opacity: 0, y: -5, scale: .98 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: -4 }} transition={{ duration: .14 }}>
      <div className="workspace-menu-heading">SEUS WORKSPACES</div>
      {workspaces.map((workspace) => <button type="button" role="option" aria-selected={active.name === workspace.name} className={`workspace-option ${active.name === workspace.name ? "workspace-option-active" : ""}`} key={workspace.name} onClick={() => { setActive(workspace); setOpen(false); onNotice(`Workspace ativo: ${workspace.name}`); }}>
        <span className="workspace-option-mark">C</span><span className="workspace-option-copy"><strong>{workspace.name}</strong><small>{workspace.description}</small></span>{active.name === workspace.name && <Check size={15} />}
      </button>)}
    </motion.div>}</AnimatePresence>
  </div>;
}

export default function App() {
  const [page, setPage] = useState<Page>("Visão geral");
  const [query, setQuery] = useState("");
  const [searchOpen, setSearchOpen] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [dark, setDark] = useState(true);
  const [notice, setNotice] = useState("");
  const [member, setMember] = useState<Member | null>(null);
  const [modal, setModal] = useState<"event" | "member" | "participant" | "organizer" | null>(null);
  const [eventList, setEventList] = useState(events);
  const [recurringTemplates, setRecurringTemplates] = useState(recurringEventTemplates);
  const [memberList] = useState(members);
  const [participantList, setParticipantList] = useState(registeredParticipants);
  const [eventSearch, setEventSearch] = useState("");

  useEffect(() => { const onKeys = (e: KeyboardEvent) => { if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "k") { e.preventDefault(); setSearchOpen((v) => !v); } if (e.key === "Escape") { setSearchOpen(false); setModal(null); setMember(null); } }; window.addEventListener("keydown", onKeys); return () => window.removeEventListener("keydown", onKeys); }, []);
  useEffect(() => { if (notice) { const t = window.setTimeout(() => setNotice(""), 2800); return () => window.clearTimeout(t); } }, [notice]);

  const go = (next: Page) => { setPage(next); setMobileOpen(false); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const submit = (e: React.FormEvent<HTMLFormElement>, label: string) => { e.preventDefault(); const form = new FormData(e.currentTarget); if (label === "Série") { const name = String(form.get("seriesName") || "Nova série").trim(); const slug = name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "serie"; const templateId = `${slug}-${Date.now().toString(36)}`; const weekday = Number(form.get("weekday")); const template = { id: templateId, name, type: String(form.get("seriesType") || "Encontro"), weekday, time: String(form.get("time") || "19:30"), location: String(form.get("location") || ""), owner: String(form.get("owner") || organizers[0].name), capacity: Number(form.get("capacity")) || 0, description: String(form.get("seriesDescription") || ""), observations: String(form.get("seriesObservations") || "") }; setRecurringTemplates((items) => [...items, template]); const firstEvent: EventItem = { id: Math.max(...eventList.map((item) => item.id), 0) + 1, name: template.name, type: template.type, date: nextDateForWeekday(template.weekday), time: template.time, location: template.location, owner: template.owner, capacity: template.capacity, description: template.description, observations: template.observations, status: "Confirmado", attendees: 0, seriesId: template.id }; setEventList((items) => [...items, firstEvent]); setModal(null); setNotice(`Série ${name} criada e adicionada à lista de eventos`); return; } if (label === "Cadastro") { const name = String(form.get("name") || "").trim(); const participant: Member = { id: Math.max(1000, ...participantList.map((item) => item.id)) + 1, name, phone: String(form.get("phone") || ""), email: String(form.get("email") || ""), city: String(form.get("city") || ""), group: "Participante", position: "Voluntário", status: "Ativo", since: new Date().toLocaleDateString("pt-BR"), avatar: avatar(name), attendance: 0, lastVisit: null }; setParticipantList((items) => [...items, participant]); } if (label === "Evento") { const seriesId = String(form.get("seriesId") || "") || undefined; const series = recurringTemplates.find((item) => item.id === seriesId); const selectedDate = String(form.get("date") || ""); if (series && new Date(`${selectedDate}T12:00:00`).getDay() !== series.weekday) { setNotice(`Este evento acontece toda ${weekdayNames[series.weekday]}. Selecione uma data nesse dia.`); return; } const newEvent: EventItem = { id: Math.max(...eventList.map((item) => item.id), 0) + 1, name: String(form.get("name") || "Novo evento"), description: String(form.get("description") || ""), date: selectedDate, time: String(form.get("time") || ""), location: String(form.get("location") || ""), type: String(form.get("type") || "Encontro"), owner: String(form.get("owner") || organizers[0].name), capacity: Number(form.get("capacity")) || undefined, observations: String(form.get("observations") || ""), status: "Confirmado", attendees: 0, seriesId }; setEventList((items) => [...items, newEvent]); } setModal(null); setNotice(label === "Evento" ? "Evento criado com sucesso" : `${label} salvo com sucesso`); };
  const filteredMembers = useMemo(() => memberList.filter((m) => `${m.name} ${m.phone} ${m.group} ${m.city}`.toLowerCase().includes(query.toLowerCase())), [memberList, query]);
  const filteredEvents = eventList.filter((ev) => `${ev.name} ${ev.type} ${ev.location}`.toLowerCase().includes(eventSearch.toLowerCase()));

  const renderPage = () => {
    switch (page) {
      case "Eventos": return <EventsPage eventList={filteredEvents} participants={participantList} onParticipantCreated={(person) => setParticipantList((items) => items.some((item) => item.id === person.id || (!!person.email && item.email === person.email)) ? items : [...items, person])} eventSearch={eventSearch} setEventSearch={setEventSearch} onNew={() => setModal("event")} onNotice={setNotice} onEventStatusChange={(id, status) => setEventList((items) => items.map((event) => event.id === id ? { ...event, status } : event))} onAttendeeAdded={(id) => setEventList((items) => items.map((event) => event.id === id ? { ...event, attendees: event.attendees + 1 } : event))} onDelete={(id) => setEventList((items) => items.filter((event) => event.id !== id))} onDuplicate={(event) => { setEventList((items) => [...items, { ...event, id: Math.max(...items.map((item) => item.id), 0) + 1, name: `${event.name} (cópia)`, status: "Em breve" }]); setNotice("Evento duplicado com sucesso"); }} />;
      case "Membros": return <MembersPage rows={filteredMembers} query={query} setQuery={setQuery} onSelect={setMember} onNew={() => setModal("member")} />;
      case "Participantes": return <ParticipantsPage participants={participantList} onNew={() => setModal("participant")} />;
      case "Organizadores": return <OrganizersPage onNew={() => setModal("organizer")} onNotice={setNotice} />;
      case "Relatórios": return <ReportsPage eventList={eventList} recurringTemplates={recurringTemplates} onNotice={setNotice} />;
      case "Configurações": return <SettingsPage onNotice={setNotice} dark={dark} setDark={setDark} />;
      case "Meu perfil": return <ProfilePage onNotice={setNotice} />;
      case "QR Code": return <QrPage onNotice={setNotice} />;
      default: return <DashboardPage onGo={go} onNotice={setNotice} />;
    }
  };

  return <div className={dark ? "app-shell dark" : "app-shell"}>
    {mobileOpen && <button className="mobile-scrim" onClick={() => setMobileOpen(false)} aria-label="Fechar menu" />}
    <aside className={`sidebar ${mobileOpen ? "sidebar-open" : ""}`}>
      <button className="brand" onClick={() => go("Visão geral")}><span className="brand-mark"><BrandLogo /></span><span className="brand-text">Presen<span className="brand-highlight">CA</span></span><span className="brand-dot">•</span></button>
      <WorkspaceSelector onNotice={setNotice} />
      <div className="nav-scroll">{["PRINCIPAL", "COMUNIDADE", "GESTÃO"].map((group) => <div className="nav-group" key={group}><div className="nav-label">{group}</div>{navigation.filter((item) => item.group === group).map(({ label, icon: Icon }) => <button key={label} onClick={() => go(label)} className={`nav-link ${page === label ? "nav-active" : ""}`}><Icon size={17} strokeWidth={1.8} /><span>{label}</span>{label === "Eventos" && <span className="nav-count">3</span>}</button>)}</div>)}
        <div className="nav-group nav-bottom-group"><div className="nav-label">PREFERÊNCIAS</div><button onClick={() => go("Configurações")} className={`nav-link ${page === "Configurações" ? "nav-active" : ""}`}><Settings size={17} strokeWidth={1.8} /><span>Configurações</span></button></div>
      </div>
      <div className="sidebar-footer"><div className="sidebar-help"><span className="help-mark"><CircleHelp size={16} /></span><div><strong>Precisa de ajuda?</strong><small>Estamos por aqui.</small></div><ArrowRight size={15} /></div><button className="profile-mini" onClick={() => go("Meu perfil")}><Avatar name="Igor Felipe" /><span className="profile-copy"><strong>Igor Felipe</strong><small>Administrador</small></span><MoreHorizontal size={18} /></button></div>
    </aside>
    <main className="main-area"><header className="topbar"><div className="topbar-left"><IconButton label="Abrir menu" className="mobile-menu-btn" onClick={() => setMobileOpen(true)}><Menu size={19} /></IconButton><div className="breadcrumbs"><span>Cristo Alegria</span><ChevronRight size={14} /><strong>{page === "Visão geral" ? "Visão geral" : page}</strong></div></div><div className="topbar-actions"><button className="search-trigger" onClick={() => setSearchOpen(true)}><Search size={15} /><span>Buscar qualquer coisa...</span><kbd><Command size={11} /> K</kbd></button><span className="topbar-divider" /><IconButton label="Alternar tema" onClick={() => setDark(!dark)}>{dark ? <Sun size={17} /> : <Moon size={17} />}</IconButton><span className="notification-wrap"><IconButton label="Notificações" onClick={() => setNotice("Você está em dia! Nenhuma notificação nova.")}><Bell size={17} /></IconButton><i className="notification-dot" /></span><button className="topbar-avatar" onClick={() => go("Meu perfil")}><Avatar name="Igor Felipe" /></button></div></header>
      <div className="page-content"><AnimatePresence mode="wait"><motion.div key={page} initial={{ opacity: 0, y: 7 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -5 }} transition={{ duration: 0.2 }}>{renderPage()}</motion.div></AnimatePresence><footer className="page-footer"><span>Coloca no feedback!! <Heart size={12} fill="currentColor" /> - Comunidade Católica Cristo Alegria. </span><span>PresenCA <b>·</b> v1.0.0</span></footer></div></main>
    <AnimatePresence>{searchOpen && <CommandPalette onClose={() => setSearchOpen(false)} onGo={(p) => { go(p); setSearchOpen(false); }} />}</AnimatePresence>
    <AnimatePresence>{member && <MemberDrawer member={member} onClose={() => setMember(null)} />}</AnimatePresence>
    <AnimatePresence>{modal && <FormModal type={modal} recurringTemplates={recurringTemplates} onClose={() => setModal(null)} onSubmit={submit} />}</AnimatePresence>
    <AnimatePresence>{notice && <motion.div className="toast" initial={{ opacity: 0, y: 15, scale: 0.97 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 8 }}><span className="toast-check"><Check size={15} /></span>{notice}<button onClick={() => setNotice("")} aria-label="Fechar"><X size={15} /></button></motion.div>}</AnimatePresence>
  </div>;
}

function DashboardPage({ onGo, onNotice }: { onGo: (p: Page) => void; onNotice: (text: string) => void }) {
  const upcoming = events.slice(0, 4);
  return <><div className="welcome-strip"><div className="welcome-copy"><div className="eyebrow welcome-eyebrow"><span className="live-dot" /> QUINTA-FEIRA, 12 DE NOVEMBRO</div><h1>Bom dia, Igor </h1><p>Veja o que está acontecendo na comunidade hoje.</p></div><button className="button button-primary" onClick={() => onGo("Eventos")}><Plus size={16} /> Novo evento</button></div>
    <div className="stats-grid">
      <StatCard label="Total de membros" value="248" delta="12%" note="vs. mês passado" icon={Users} color="purple" trend="up" />
      <StatCard label="Presentes hoje" value="36" delta="8,4%" note="vs. mês passado" icon={UserRound} color="green" trend="up" />
      <StatCard label="Faltas hoje" value="4" delta="2,1%" note="vs. mês passado" icon={CircleAlert} color="orange" trend="down" />
      <StatCard label="Eventos este mês" value="12" delta="2" note="a mais que outubro" icon={CalendarDays} color="blue" trend="up" />
    </div>
    <div className="charts-grid"><section className="card chart-card"><CardHead title="Presença ao longo do tempo" subtitle="Acompanhe o engajamento da comunidade." action={<button className="select-chip">Últimos 6 meses <ChevronDown size={13} /></button>} /><div className="chart-area"><ResponsiveContainer width="100%" height="100%"><AreaChart data={monthly} margin={{ top: 12, right: 8, left: -20, bottom: 0 }}><defs><linearGradient id="presenceFill" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#49856f" stopOpacity={0.17} /><stop offset="95%" stopColor="#49856f" stopOpacity={0} /></linearGradient></defs><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="var(--line)" /><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{ fill: "var(--muted)", fontSize: 11 }} dy={8} /><YAxis tickLine={false} axisLine={false} tick={{ fill: "var(--muted)", fontSize: 11 }} /><Tooltip contentStyle={{ borderRadius: 10, border: "1px solid var(--line)", fontSize: 12, boxShadow: "0 5px 22px #18231d12", background: "var(--surface)" }} /><Area type="monotone" dataKey="presenças" stroke="#49856f" strokeWidth={2.4} fill="url(#presenceFill)" activeDot={{ r: 5, fill: "#49856f", stroke: "#fff", strokeWidth: 2 }} /></AreaChart></ResponsiveContainer></div><div className="chart-foot"><span><i className="legend-dot green-dot" />Presenças registradas</span><span>+18,6% este semestre <ArrowUpRight size={13} /></span></div></section>
    <section className="card chart-card event-chart-card"><CardHead title="Presença por evento" subtitle="Últimos encontros realizados." action={<IconButton label="Mais opções" onClick={() => onGo("Relatórios")}><Ellipsis size={18} /></IconButton>} /><div className="event-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={eventAttendance} margin={{ top: 16, right: 5, left: -23, bottom: 0 }} barGap={5}><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="var(--line)" /><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{ fill: "var(--muted)", fontSize: 10 }} dy={8} /><YAxis tickLine={false} axisLine={false} tick={{ fill: "var(--muted)", fontSize: 10 }} /><Tooltip contentStyle={{ borderRadius: 10, border: "1px solid var(--line)", fontSize: 12, background: "var(--surface)" }} /><Bar dataKey="presentes" name="Presentes" fill="#49856f" radius={[4, 4, 0, 0]} maxBarSize={23} /><Bar dataKey="ausentes" name="Ausentes" fill="#eadbc8" radius={[4, 4, 0, 0]} maxBarSize={23} /></BarChart></ResponsiveContainer></div><div className="chart-foot"><span><i className="legend-dot green-dot" />Presentes</span><span><i className="legend-dot peach-dot" />Ausentes</span></div></section></div>
    <div className="bottom-grid dashboard-bottom-grid"><section className="card list-card"><CardHead title="Próximos eventos" subtitle="Eventos da sua comunidade chegando." action={<button className="text-link" onClick={() => onGo("Eventos")}>Ver todos <ArrowRight size={14} /></button>} /><div className="upcoming-list">{upcoming.map((event, i) => <button className="upcoming-row" key={event.id} onClick={() => onGo("Eventos")}><div className={`event-date-icon tone-${i % 4}`}><span>{new Date(`${event.date}T12:00:00`).toLocaleDateString("pt-BR", { day: "2-digit" })}</span><small>{new Date(`${event.date}T12:00:00`).toLocaleDateString("pt-BR", { month: "short" }).replace(".", "").toUpperCase()}</small></div><div className="upcoming-info"><strong>{event.name}</strong><span><Clock3 size={12} />{event.time}<span className="meta-dot">·</span><MapPin size={12} />{event.location}</span></div><Badge tone={i < 2 ? "green" : "neutral"} dot>{i < 2 ? "Confirmado" : "Em breve"}</Badge><ArrowRight className="row-arrow" size={15} /></button>)}</div></section>
    </div>
  </>;
}

function StatCard({ label, value, delta, note, icon: Icon, color, trend }: { label: string; value: string; delta: string; note: string; icon: LucideIcon; color: string; trend: string }) { return <div className="card stat-card"><div className="stat-top"><span>{label}</span><span className={`stat-icon stat-${color}`}><Icon size={17} /></span></div><div className="stat-value">{value}</div><div className="stat-bottom"><span className={`stat-delta delta-${trend}`}>{trend === "up" ? <ArrowUpRight size={13} /> : <ArrowDownRight size={13} />}{delta}</span><span>{note}</span></div><div className={`stat-sparkline spark-${color}`}><svg viewBox="0 0 88 24" preserveAspectRatio="none"><path d={trend === "up" ? "M1 20 C11 19 15 15 23 18 S37 12 43 15 S54 6 62 11 S75 3 87 4" : "M1 5 C11 6 15 9 23 7 S37 13 43 10 S54 18 62 13 S75 20 87 19"} fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" /></svg></div></div>; }

function EventsPage({ eventList, participants, onParticipantCreated, eventSearch, setEventSearch, onNew, onNotice, onEventStatusChange, onAttendeeAdded, onDelete, onDuplicate }: { eventList: EventItem[]; participants: Member[]; onParticipantCreated: (person: Member) => void; eventSearch: string; setEventSearch: (v: string) => void; onNew: () => void; onNotice: (s: string) => void; onEventStatusChange: (id: number, status: EventItem["status"]) => void; onAttendeeAdded: (id: number) => void; onDelete: (id: number) => void; onDuplicate: (event: EventItem) => void }) {
 const [confirming, setConfirming] = useState<EventItem | null>(null);
 const [selectedEvent, setSelectedEvent] = useState<EventItem | null>(null);
 const [eventRecords, setEventRecords] = useState(attendance);
 if (selectedEvent) return <EventDetailsPage event={selectedEvent} records={eventRecords.filter((item) => item.event.id === selectedEvent.id)} candidates={[...members, ...participants]} onBack={() => setSelectedEvent(null)} onNotice={onNotice} onEventStatusChange={(id, status) => { onEventStatusChange(id, status); setSelectedEvent((current) => current ? { ...current, status } : current); }} onStatusChange={(id, status) => setEventRecords((items) => items.map((item) => item.id === id ? { ...item, status } : item))} onAdd={(person) => { const newRecord = { id: Math.max(...eventRecords.map((item) => item.id), 0) + 1, member: person, event: selectedEvent, status: person.group === "Participante" ? "—" : "Ausente" }; setEventRecords((items) => [...items, newRecord]); if (person.id >= 1000) onParticipantCreated(person); setSelectedEvent((current) => current ? { ...current, attendees: current.attendees + 1 } : current); onAttendeeAdded(selectedEvent.id); onNotice(`${person.name} foi adicionado ao evento`); }} />;
 return <><SectionTitle eyebrow="SUA COMUNIDADE" title="Eventos" subtitle="Organize encontros e acompanhe quem vai participar." action={<button className="button button-primary" onClick={onNew}><Plus size={16} /> Novo evento</button>} /><div className="mini-stats"><span><strong>12</strong> eventos este mês</span><i /><span><strong>286</strong> inscritos</span><i /><span><strong>4</strong> próximos eventos</span></div><section className="card data-card"><div className="table-toolbar"><div className="search-field"><Search size={15} /><input placeholder="Buscar evento..." value={eventSearch} onChange={(e) => setEventSearch(e.target.value)} /><kbd>/</kbd></div><div className="toolbar-actions"><button className="button button-secondary" onClick={() => onNotice("Mostrando todos os tipos de evento")}><ListFilter size={14} />Filtros<ChevronDown size={12} /></button><button className="button button-secondary" onClick={() => onNotice("Lista pronta para exportar")}><Download size={14} />Exportar</button></div></div><div className="table-wrap"><table><thead><tr><th>EVENTO</th><th>TIPO</th><th>DATA E HORA</th><th>LOCAL</th><th>RESPONSÁVEL</th><th>STATUS</th><th>INSCRITOS</th><th /></tr></thead><tbody>{eventList.map((ev, i) => <tr key={ev.id}><td><div className="event-table-name"><span className={`table-event-icon te-${i % 4}`}><CalendarDays size={15} /></span><button className="event-open-button" onClick={() => setSelectedEvent(ev)}>{ev.name}<ArrowRight size={12} /></button></div></td><td>{ev.type}</td><td><strong className="table-strong">{formatDate(ev.date)}</strong><small className="table-sub"> às {ev.time}</small></td><td>{ev.location}</td><td><span className="owner-cell"><Avatar name={ev.owner} size="small" />{ev.owner}</span></td><td><Badge dot tone={ev.status === "Confirmado" ? "green" : ev.status === "Concluído" ? "blue" : "neutral"}>{ev.status}</Badge></td><td><span className="attendee-count"><Users size={13} />{ev.attendees}</span></td><td><details className="row-actions"><summary className="table-menu" aria-label={`Ações de ${ev.name}`}><MoreHorizontal size={17} /></summary><div className="row-action-menu"><button onClick={() => setSelectedEvent(ev)}>Ver detalhes</button><button onClick={() => { onNotice(`Edição de ${ev.name} aberta`); document.querySelectorAll(".row-actions[open]").forEach((el) => el.removeAttribute("open")); }}>Editar</button><button onClick={() => { onDuplicate(ev); document.querySelectorAll(".row-actions[open]").forEach((el) => el.removeAttribute("open")); }}>Duplicar</button><button className="row-action-delete" onClick={() => { setConfirming(ev); document.querySelectorAll(".row-actions[open]").forEach((el) => el.removeAttribute("open")); }}>Excluir</button></div></details></td></tr>)}</tbody></table>{eventList.length === 0 && <EmptyState title="Nenhum evento encontrado" description="Tente ajustar sua busca ou crie um novo evento." icon={CalendarDays} />}</div><div className="table-pagination"><span>Mostrando <strong>{eventList.length}</strong> de <strong>{eventList.length}</strong> eventos</span><div><button disabled><ChevronLeft size={15} /></button><button className="page-number active-page">1</button><button disabled><ChevronRight size={15} /></button></div></div></section><div className="event-note"><span className="note-icon"><Sparkles size={16} /></span><span><strong>Dica:</strong> Eventos com lista de inscrição aberta aparecem automaticamente para os participantes.</span><button onClick={() => onNotice("Ajuda sobre inscrições aberta")}>Saiba mais <ArrowRight size={13} /></button></div><AnimatePresence>{confirming && <motion.div className="modal-overlay" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onMouseDown={(e) => e.target === e.currentTarget && setConfirming(null)}><motion.section className="form-modal confirm-modal" initial={{ opacity: 0, y: 12, scale: .98 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 8 }}><span className="confirm-icon"><CircleAlert size={19} /></span><h2>Excluir este evento?</h2><p><strong>{confirming.name}</strong> será removido desta lista de eventos.</p><div className="form-modal-actions"><button className="button button-secondary" onClick={() => setConfirming(null)}>Cancelar</button><button className="button button-danger" onClick={() => { onDelete(confirming.id); setConfirming(null); onNotice("Evento excluído"); }}>Excluir evento</button></div></motion.section></motion.div>}</AnimatePresence></>;
}

function EventDetailsPage({ event, records, candidates, onBack, onNotice, onEventStatusChange, onAdd, onStatusChange }: { event: EventItem; records: typeof attendance; candidates: Member[]; onBack: () => void; onNotice: (message: string) => void; onEventStatusChange: (id: number, status: EventItem["status"]) => void; onAdd: (person: Member) => void; onStatusChange: (id: number, status: string) => void }) {
  const [filter, setFilter] = useState("Todos");
  const [search, setSearch] = useState("");
  const [addOpen, setAddOpen] = useState(false);
  const memberCount = records.filter((item) => item.member.group !== "Participante").length;
  const participantCount = records.length - memberCount;
  const people = records.filter((item) => (filter === "Todos" || (filter === "Membros" ? item.member.group !== "Participante" : item.member.group === "Participante")) && `${item.member.name} ${item.member.group} ${item.member.city}`.toLowerCase().includes(search.toLowerCase()));
  const info = eventDetails[event.id] || { description: event.description || "", capacity: event.capacity || 0, observations: event.observations || "" };
  return <>
    <button className="event-back-link" onClick={onBack}><ChevronLeft size={15} />Voltar para eventos</button>
    <div className="event-detail-heading"><div><div className="eyebrow">EVENTOS <ChevronRight size={12} /> DETALHES DO EVENTO</div><h1>{event.name}</h1><p>{event.type} <span>·</span> Criado por {event.owner}</p></div><div className="event-detail-heading-actions"><label className="event-status-control"><span>STATUS</span><select className={`event-state-select event-state-${event.status.toLowerCase().replaceAll(" ", "-")}`} aria-label="Status do evento" value={event.status === "Concluído" ? "Confirmado" : event.status} onChange={(e) => { onEventStatusChange(event.id, e.target.value as EventItem["status"]); onNotice(`Status de ${event.name} atualizado`); }}><option value="Confirmado">Confirmado</option><option value="Em breve">Em breve</option><option value="Cancelado">Cancelado</option></select></label></div></div>
    <section className="card event-detail-hero"><div className="event-detail-description"><span className="event-detail-icon"><CalendarDays size={19} /></span><h2>Sobre este evento</h2><p>{event.description || info?.description || "Encontro da comunidade Cristo Alegria. Confira os detalhes e a lista de participantes abaixo."}</p><div className="event-detail-facts"><div><CalendarDays size={15} /><span><small>DATA</small><strong>{new Date(`${event.date}T12:00:00`).toLocaleDateString("pt-BR", { weekday: "long", day: "2-digit", month: "long", year: "numeric" })}</strong></span></div><div><Clock3 size={15} /><span><small>HORÁRIO</small><strong>{event.time}</strong></span></div><div><MapPin size={15} /><span><small>LOCAL</small><strong>{event.location}</strong></span></div><div><UserRound size={15} /><span><small>RESPONSÁVEL</small><strong>{event.owner}</strong></span></div></div>{info?.observations && <div className="event-observation"><MessageSquare size={14} /><span><strong>Observações</strong>{info.observations}</span></div>}</div><div className="event-detail-side"><div className="event-detail-capacity"><span className="eyebrow">INSCRITOS</span><strong>{event.attendees}<small>{info?.capacity ? ` / ${info.capacity}` : ""}</small></strong><div className="progress-track"><span style={{ width: `${Math.min(100, (event.attendees / (info?.capacity || event.attendees || 1)) * 100)}%` }} /></div><small>{info?.capacity ? `${Math.max(info.capacity - event.attendees, 0)} vagas disponíveis` : "participantes inscritos"}</small></div><div className="event-detail-mini-stat"><span className="mini-stat-icon"><Users size={15} /></span><div><strong>{memberCount}</strong><small>membros na lista</small></div></div></div></section>
    <div className="event-attendance-title"><div><h2>Participantes do evento</h2><p>Membros e participantes inscritos. O status de participação fica disponível para membros.</p></div><div className="event-detail-heading-actions"><button className="button button-primary" onClick={() => setAddOpen(true)}><UserPlus size={14} />Adicionar participante</button><button className="button button-secondary" onClick={() => onNotice("Lista de participantes exportada")}><Download size={14} />Exportar lista</button></div></div>
    <div className="event-presence-stats event-roster-stats"><div className="card"><span className="presence-stat-dot dot-total" /><span><small>TOTAL NA LISTA</small><strong>{records.length}</strong></span></div><div className="card"><span className="presence-stat-dot dot-present" /><span><small>MEMBROS</small><strong>{memberCount}</strong></span></div><div className="card"><span className="presence-stat-dot dot-justified" /><span><small>PARTICIPANTES</small><strong>{participantCount}</strong></span></div><div className="card"><span className="presence-stat-dot dot-absent" /><span><small>VAGAS DISPONÍVEIS</small><strong>{info?.capacity ? Math.max(info.capacity - event.attendees, 0) : "—"}</strong></span></div></div>
    <section className="card data-card event-attendees-card"><div className="table-toolbar"><div className="search-field"><Search size={15} /><input placeholder="Buscar participante..." value={search} onChange={(e) => setSearch(e.target.value)} /></div><div className="toolbar-actions"><div className="attendance-filter-tabs">{["Todos", "Membros", "Participantes"].map((audience) => <button key={audience} className={filter === audience ? "attendance-filter-active" : ""} onClick={() => setFilter(audience)}>{audience}</button>)}</div></div></div><div className="table-wrap"><table><thead><tr><th>PARTICIPANTE</th><th>TIPO</th><th>CIDADE</th><th>STATUS</th></tr></thead><tbody>{people.map((item) => { const isMember = item.member.group !== "Participante"; return <tr key={item.id}><td><div className="person-cell"><Avatar name={item.member.name} src={item.member.avatar} /><div className="person-name"><strong>{item.member.name}</strong><small>{item.member.email}</small></div></div></td><td><Badge tone="neutral">{isMember ? "Membro" : "Participante"}</Badge></td><td>{item.member.city}</td><td>{isMember ? <select className={`event-status-select event-status-${item.status.toLowerCase()}`} aria-label={`Status de ${item.member.name}`} value={item.status} onChange={(e) => { onStatusChange(item.id, e.target.value); onNotice(`Status de ${item.member.name} atualizado`); }}><option value="Presente">Presente</option><option value="Ausente">Ausente</option><option value="Justificado">Justificado</option></select> : <span className="participant-no-status">—</span>}</td></tr>; })}</tbody></table>{people.length === 0 && <EmptyState title={filter === "Membros" ? "Nenhum membro encontrado" : filter === "Participantes" ? "Nenhum participante encontrado" : "Lista vazia"} description="Ajuste sua busca ou adicione pessoas a este evento." icon={Users} />}</div><div className="table-pagination"><span>Exibindo <strong>{people.length}</strong> de <strong>{records.length}</strong> inscritos neste evento</span><div><button disabled><ChevronLeft size={15} /></button><button className="page-number active-page">1</button><button disabled><ChevronRight size={15} /></button></div></div></section>
    <AnimatePresence>{addOpen && <AddEventParticipantModal event={event} candidates={candidates} existing={records.map((record) => record.member)} onClose={() => setAddOpen(false)} onAdd={(person) => { onAdd(person); setFilter("Todos"); setAddOpen(false); }} />}</AnimatePresence>
  </>;
}

function AddEventParticipantModal({ event, candidates, existing, onClose, onAdd }: { event: EventItem; candidates: Member[]; existing: Member[]; onClose: () => void; onAdd: (person: Member) => void }) {
  const [tab, setTab] = useState<"Membros" | "Participantes" | "Novo cadastro">("Membros");
  const [search, setSearch] = useState("");
  const alreadyAdded = (person: Member) => existing.some((item) => item.id === person.id || item.email === person.email);
  const list = candidates.filter((person) => tab === "Membros" ? person.id < 1000 : person.id >= 1000)
    .filter((person) => `${person.name} ${person.email} ${person.city}`.toLowerCase().includes(search.toLowerCase()));

  return <motion.div className="modal-overlay" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
    <motion.section className="form-modal add-attendee-modal" role="dialog" aria-modal="true" aria-labelledby="add-attendee-title" initial={{ opacity: 0, y: 15, scale: .98 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 10 }}>
      <div className="form-modal-head"><span className="form-modal-icon"><UserPlus size={18} /></span><div><h2 id="add-attendee-title">Adicionar participante</h2><p>Inclua alguém na lista de {event.name}.</p></div><IconButton label="Fechar" onClick={onClose}><X size={17} /></IconButton></div>
      <div className="add-attendee-tabs">{(["Membros", "Participantes", "Novo cadastro"] as const).map((item) => <button type="button" key={item} className={tab === item ? "add-attendee-tab-active" : ""} onClick={() => { setTab(item); setSearch(""); }}>{item}</button>)}</div>
      {tab !== "Novo cadastro" ? <>
        <div className="search-field add-attendee-search"><Search size={15} /><input autoFocus placeholder={`Buscar ${tab.toLowerCase()}...`} value={search} onChange={(e) => setSearch(e.target.value)} /></div>
        <div className="add-attendee-list">{list.map((person) => { const added = alreadyAdded(person); return <div className="add-attendee-row" key={`${person.id}-${person.email}`}><Avatar name={person.name} src={person.avatar} /><span className="add-attendee-person"><strong>{person.name}</strong><small>{person.email} · {person.city}</small></span><button type="button" className={`button ${added ? "button-secondary" : "button-primary"}`} disabled={added} onClick={() => onAdd(person)}>{added ? <><Check size={13} />Adicionado</> : <><Plus size={13} />Adicionar</>}</button></div>; })}{list.length === 0 && <EmptyState title="Ninguém encontrado" description="Tente outro nome ou cadastre uma pessoa nova." icon={Users} />}</div>
      </> : <form onSubmit={(e) => { e.preventDefault(); const form = new FormData(e.currentTarget); const name = String(form.get("name")).trim(); const email = String(form.get("email")).trim(); const city = String(form.get("city")).trim(); const phone = String(form.get("phone")).trim(); const person: Member = { id: Math.max(1000, ...candidates.map((candidate) => candidate.id)) + 1, name, email, city, phone, group: "Participante", position: "Voluntário", status: "Ativo", since: new Date().toLocaleDateString("pt-BR"), avatar: avatar(name), attendance: 0, lastVisit: null }; onAdd(person); }}>
        <div className="modal-form-grid"><label className="settings-label field-full">NOME COMPLETO<input required name="name" autoFocus placeholder="Nome e sobrenome" /></label><label className="settings-label">TELEFONE<input required name="phone" type="tel" placeholder="(62) 99999-9999" /></label><label className="settings-label">EMAIL<input name="email" type="email" placeholder="pessoa@email.com" /></label><label className="settings-label field-full">CIDADE<input name="city" placeholder="Sua cidade" /></label></div>
        <div className="form-modal-actions"><button type="button" className="button button-secondary" onClick={onClose}>Cancelar</button><button type="submit" className="button button-primary"><UserPlus size={14} />Cadastrar e adicionar</button></div>
      </form>}
      {tab !== "Novo cadastro" && <div className="add-attendee-footer"><span>Quem você procura não está na lista?</span><button type="button" onClick={() => setTab("Novo cadastro")}>Cadastrar novo participante <ArrowRight size={13} /></button></div>}
    </motion.section>
  </motion.div>;
}

function MembersPage({ rows, query, setQuery, onSelect, onNew }: { rows: Member[]; query: string; setQuery: (s: string) => void; onSelect: (m: Member) => void; onNew: () => void }) {
  const [group, setGroup] = useState("Todos os ministérios");
  const [position, setPosition] = useState("Todas as posições");
  const positions: Member["position"][] = ["Consagrado", "Aspirante", "Vocacionado", "Voluntário"];
  const positionTone: Record<Member["position"], string> = { Consagrado: "purple", Aspirante: "blue", Vocacionado: "orange", "Voluntário": "green" };
  const groups = ["Comunicação", "Eventos", "Lanchonete", "Música", "Acolhida"];
  const visible = rows.filter((member) => (group === "Todos os ministérios" || member.group === group) && (position === "Todas as posições" || member.position === position));

  return <>
    <SectionTitle eyebrow="COMUNIDADE" title="Membros" subtitle="Lista de membros que fazem parte da comunidade." action={<button className="button button-primary" onClick={onNew}><Plus size={16} />Novo membro</button>} />
    <div className="member-metrics"><div><span className="metric-icon metric-purple"><Users size={17} /></span><div><strong>248</strong><small>membros no total</small></div></div><div><span className="metric-icon metric-green"><UserRound size={17} /></span><div><strong>216</strong><small>membros ativos</small></div></div><div><span className="metric-icon metric-amber"><CalendarDays size={17} /></span><div><strong>8</strong><small>novos este mês</small></div></div><div className="metric-growth"><ArrowUpRight size={14} />12% <span>este mês</span></div></div>
    <section className="card data-card"><div className="table-toolbar"><div className="search-field"><Search size={15} /><input placeholder="Buscar por nome, telefone ou grupo..." value={query} onChange={(e) => setQuery(e.target.value)} /></div><div className="toolbar-actions"><select className="filter-select" value={group} onChange={(e) => setGroup(e.target.value)}><option>Todos os ministérios</option>{groups.map((item) => <option key={item}>{item}</option>)}</select><select className="filter-select" aria-label="Filtrar por posição" value={position} onChange={(e) => setPosition(e.target.value)}><option>Todas as posições</option>{positions.map((item) => <option key={item}>{item}</option>)}</select></div></div>
      <div className="table-wrap"><table><thead><tr><th>MEMBRO</th><th>TELEFONE</th><th>CIDADE</th><th>MINISTÉRIO</th><th>POSIÇÃO</th><th>STATUS</th><th>INGRESSOU EM</th><th>ÚLTIMA VISITA</th><th /></tr></thead><tbody>{visible.slice(0, 9).map((member) => <tr key={member.id} className="clickable-row" onClick={() => onSelect(member)}><td><div className="person-cell"><Avatar name={member.name} src={member.avatar} /><div className="person-name"><strong>{member.name}</strong><small>{member.email}</small></div></div></td><td>{member.phone}</td><td>{member.city}</td><td><Badge tone="neutral">{member.group}</Badge></td><td><Badge tone={positionTone[member.position]}>{member.position}</Badge></td><td><Badge dot tone={member.status === "Ativo" ? "green" : "neutral"}>{member.status}</Badge></td><td>{member.since}</td><td><div className="last-visit-cell"><strong>{member.lastVisit?.date || "Sem visitas"}</strong><small>{member.lastVisit?.event || "Ainda não participou"}</small></div></td><td><button className="table-menu" aria-label={`Ver membro ${member.name}`}><ArrowRight size={15} /></button></td></tr>)}</tbody></table>{visible.length === 0 && <EmptyState title="Nenhum membro encontrado" description="Tente outra busca ou ajuste os filtros." icon={Users} />}</div>
      <div className="table-pagination"><span>Mostrando <strong>{Math.min(9, visible.length)}</strong> de <strong>{visible.length}</strong> membros</span><div><button disabled><ChevronLeft size={15} /></button><button className="page-number active-page">1</button><button disabled><ChevronRight size={15} /></button></div></div>
    </section>
  </>;
}
function ParticipantsPage({ participants, onNew }: { participants: Member[]; onNew: () => void }) {
  const [search, setSearch] = useState("");
  const [qrOpen, setQrOpen] = useState(false);
  const newsGroupInviteUrl = "https://chat.whatsapp.com/ItKJoQ59AdgFeuFcw9fvai?s=cl&p=i&iam=2";
  const people = participants.filter((person) => `${person.name} ${person.email} ${person.phone} ${person.city} ${person.lastVisit?.event || ""}`.toLowerCase().includes(search.toLowerCase()));

  return <>
    <SectionTitle eyebrow="ACESSO LIVRE" title="Participantes" subtitle="Acompanhe os visitantes cadastrados na comunidade." action={<button className="button button-primary" onClick={onNew}><Plus size={16} />Novo participante</button>} />
    <section className="card participant-hero">
      <div className="participant-hero-copy">
        <span className="eyebrow">GRUPO INFORMATIVO</span>
        <h2>Convide para o News</h2>
        <p>Adicione um participante ao grupo informativo no WhatsApp pelo botão abaixo</p>
        <button className="button button-primary participant-news-qr-button" onClick={() => setQrOpen(true)}><QrCode size={15} />Abrir QR Code</button>
      </div>
      <div className="participant-illustration"><div className="illustration-orbit orbit-one" /><div className="illustration-orbit orbit-two" /><div className="illustration-people"><Users size={55} /></div></div>
    </section>
    <div className="participant-stats"><div className="card"><span className="participant-stat-icon peach"><UserPlus size={16} /></span><strong>{participants.length}</strong><small>visitantes cadastrados</small></div><div className="card"><span className="participant-stat-icon lavender"><Users size={16} /></span><strong>{participants.filter((person) => person.lastVisit).length}</strong><small>com visita registrada</small></div><div className="card"><span className="participant-stat-icon mint"><CalendarDays size={16} /></span><strong>{participants.filter((person) => !person.lastVisit).length}</strong><small>sem visita registrada</small></div></div>
    <section className="card data-card participants-directory"><div className="table-toolbar"><div className="search-field"><Search size={15} /><input placeholder="Buscar por nome, telefone, cidade ou evento..." value={search} onChange={(e) => setSearch(e.target.value)} /></div></div><div className="table-wrap"><table><thead><tr><th>PESSOA</th><th>TELEFONE</th><th>CIDADE</th><th>ÚLTIMA VISITA</th></tr></thead><tbody>{people.map((person) => <tr key={`visitor-${person.id}`}><td><div className="person-cell"><Avatar name={person.name} src={person.avatar} /><div className="person-name"><strong>{person.name}</strong><small>{person.email}</small></div></div></td><td>{person.phone}</td><td>{person.city || "—"}</td><td><div className="last-visit-cell"><strong>{person.lastVisit?.date || "Sem visitas"}</strong><small>{person.lastVisit?.event || "Ainda não participou"}</small></div></td></tr>)}</tbody></table>{people.length === 0 && <EmptyState title="Nenhuma pessoa encontrada" description="Tente ajustar sua busca." icon={Users} />}</div><div className="table-pagination"><span>Mostrando <strong>{people.length}</strong> de <strong>{people.length}</strong> pessoas</span><div><button disabled><ChevronLeft size={15} /></button><button className="page-number active-page">1</button><button disabled><ChevronRight size={15} /></button></div></div></section>
    <AnimatePresence>{qrOpen && <motion.div className="modal-overlay" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onMouseDown={(event) => event.target === event.currentTarget && setQrOpen(false)}><motion.section className="form-modal news-qr-modal" initial={{ opacity: 0, y: 12, scale: .98 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 8 }}><div className="form-modal-head"><span className="form-modal-icon"><QrCode size={18} /></span><div><h2>QR Code do grupo News</h2><p>Aponte a câmera para entrar no grupo do WhatsApp.</p></div><button className="icon-btn" aria-label="Fechar" onClick={() => setQrOpen(false)}><X size={17} /></button></div><div className="news-qr-frame"><img src={`https://api.qrserver.com/v1/create-qr-code/?size=240x240&data=${encodeURIComponent(newsGroupInviteUrl)}`} alt="QR Code de convite do grupo WhatsApp News" /></div><p className="news-qr-caption">Cristo Alegria · Grupo informativo</p><div className="form-modal-actions"><button className="button button-secondary" onClick={() => setQrOpen(false)}>Fechar</button></div></motion.section></motion.div>}</AnimatePresence>
  </>;
}
function OrganizersPage({ onNew, onNotice }: { onNew: () => void; onNotice: (message: string) => void }) { return <><SectionTitle eyebrow="EQUIPE" title="Organizadores" subtitle="Gerencie os acessos e as permissões da equipe." action={<button className="button button-primary" onClick={onNew}><Plus size={16} />Adicionar organizador</button>} /><section className="card data-card"><div className="table-toolbar"><div className="table-toolbar-heading"><h3>Equipe de organizadores</h3><span>{organizers.length} pessoas</span></div></div><div className="table-wrap"><table><thead><tr><th>ORGANIZADOR</th><th>PERMISSÃO</th><th>EMAIL</th><th>TELEFONE</th><th>STATUS</th><th /></tr></thead><tbody>{organizers.map((item) => <tr key={item.id}><td><div className="person-cell"><Avatar name={item.name} /><strong>{item.name}</strong></div></td><td><Badge tone={item.permission === "Administradora" ? "purple" : "neutral"}>{item.permission}</Badge></td><td>{item.email}</td><td>{item.phone}</td><td><Badge dot tone={item.status === "Ativo" ? "green" : "orange"}>{item.status}</Badge></td><td><button className="table-menu" onClick={() => onNotice(`Gerenciar ${item.name}`)}><MoreHorizontal size={17} /></button></td></tr>)}</tbody></table></div></section></>; }

function ReportsPage({ eventList, recurringTemplates, onNotice }: { eventList: EventItem[]; recurringTemplates: RecurringEventTemplate[]; onNotice: (message: string) => void }) {
  const [eventSelection, setEventSelection] = useState("all");
  const [period, setPeriod] = useState("all");
  const [referenceDate, setReferenceDate] = useState(() => { const date = new Date(); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`; });
  const periodEvents = eventList.filter((event) => {
    if (event.status === "Cancelado") return false;
    if (period === "all") return true;
    const [year, month, day] = event.date.split("-").map(Number);
    const [referenceYear, referenceMonth, referenceDay] = referenceDate.split("-").map(Number);
    if (period === "day") return year === referenceYear && month === referenceMonth && day === referenceDay;
    if (period === "month") return year === referenceYear && month === referenceMonth;
    if (period === "semester") return year === referenceYear && Math.floor((month - 1) / 6) === Math.floor((referenceMonth - 1) / 6);
    return year === referenceYear;
  });
  const reportEvents = periodEvents.filter((event) => {
    if (eventSelection === "all") return true;
    if (eventSelection.startsWith("series:")) return event.seriesId === eventSelection.slice(7);
    return event.id === Number(eventSelection.slice(6));
  }).sort((a, b) => a.date.localeCompare(b.date));
  const totalParticipants = reportEvents.reduce((total, event) => total + event.attendees, 0);
  const averageParticipants = reportEvents.length ? Math.round(totalParticipants / reportEvents.length) : 0;
  const monthlyTotals = reportEvents.reduce<Record<string, { month: string; inscritos: number; eventos: number }>>((totals, event) => {
    const date = new Date(`${event.date}T12:00:00`);
    const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
    const month = date.toLocaleDateString("pt-BR", { month: "short", year: "2-digit" }).replace(".", "");
    totals[key] = totals[key] || { month, inscritos: 0, eventos: 0 };
    totals[key].inscritos += event.attendees;
    totals[key].eventos += 1;
    return totals;
  }, {});
  const chartData = Object.entries(monthlyTotals).sort(([a], [b]) => a.localeCompare(b)).map(([, value]) => value);
  const periodLabel = period === "all" ? "Desde o início" : period === "day" ? "Dia" : period === "month" ? "Mês" : period === "semester" ? "Semestre" : "Ano";

  return <>
    <SectionTitle eyebrow="DADOS DA COMUNIDADE" title="Relatórios" subtitle="Acompanhe as ocorrências e os resultados das séries recorrentes." action={<button className="button button-primary" onClick={() => onNotice("Relatório preparado para exportação")}><Download size={15} />Exportar relatório</button>} />
    <section className="card report-filters"><div className="report-filter-head"><div><h3>Filtros do relatório</h3><p>Veja uma série recorrente consolidada ou uma ocorrência específica.</p></div></div><div className="report-filter-grid report-event-filters">
      <label>SÉRIE OU EVENTO<select value={eventSelection} onChange={(e) => setEventSelection(e.target.value)}><option value="all">Todos os eventos</option><optgroup label="Séries recorrentes">{recurringTemplates.map((template) => <option key={template.id} value={`series:${template.id}`}>{template.name} · consolidado</option>)}</optgroup><optgroup label="Ocorrências individuais">{eventList.filter((event) => event.status !== "Cancelado").map((event) => <option key={event.id} value={`event:${event.id}`}>{event.name} · {formatDate(event.date)}</option>)}</optgroup></select></label>
      <label>PERÍODO<select value={period} onChange={(e) => setPeriod(e.target.value)}><option value="day">Dia</option><option value="month">Mês</option><option value="semester">Semestre</option><option value="year">Ano</option><option value="all">Desde o início</option></select></label>
      {period !== "all" && <label>DATA DE REFERÊNCIA<input className="report-date-input" type="date" value={referenceDate} onChange={(e) => setReferenceDate(e.target.value)} /></label>}
    </div></section>
    <div className="report-summary-grid"><StatCard label="Ocorrências no período" value={String(reportEvents.length)} delta={periodLabel} note="eventos incluídos" icon={CalendarDays} color="blue" trend="up" /><StatCard label="Inscritos acumulados" value={totalParticipants.toLocaleString("pt-BR")} delta="total" note="nas ocorrências filtradas" icon={Users} color="purple" trend="up" /><StatCard label="Média de inscritos" value={String(averageParticipants)} delta="por evento" note="nesta seleção" icon={ChartNoAxesCombined} color="green" trend="up" /></div>
    <section className="card report-chart-card"><CardHead title="Inscritos por mês" subtitle="Os valores somam todas as ocorrências da série selecionada." /><div className="report-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={chartData} margin={{ top: 10, right: 10, left: -18, bottom: 0 }}><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="var(--line)" /><XAxis dataKey="month" tickLine={false} axisLine={false} tick={{ fill: "var(--muted)", fontSize: 10 }} /><YAxis allowDecimals={false} tickLine={false} axisLine={false} tick={{ fill: "var(--muted)", fontSize: 10 }} /><Tooltip contentStyle={{ borderRadius: 10, border: "1px solid var(--line)", fontSize: 11, background: "var(--surface)" }} /><Bar dataKey="inscritos" name="Inscritos" fill="#49856f" radius={[5, 5, 0, 0]} maxBarSize={36} /></BarChart></ResponsiveContainer>{chartData.length === 0 && <div className="report-chart-empty">Nenhum evento encontrado para esses filtros.</div>}</div></section>
    <section className="card report-detail-card"><CardHead title={eventSelection.startsWith("series:") ? `Ocorrências de ${recurringTemplates.find((item) => item.id === eventSelection.slice(7))?.name || "evento"}` : "Eventos no período"} subtitle="Cada linha representa uma ocorrência; a seleção de série soma seus resultados." /><div className="report-table"><div className="report-table-row report-table-head"><span>EVENTO</span><span>DATA</span><span>SÉRIE</span><span>INSCRITOS</span><span>STATUS</span></div>{reportEvents.map((event) => <div className="report-table-row" key={event.id}><strong>{event.name}</strong><span>{formatDate(event.date)}</span><span>{event.seriesId ? recurringTemplates.find((item) => item.id === event.seriesId)?.name : "Avulso"}</span><span>{event.attendees}</span><span><Badge dot tone={event.status === "Confirmado" ? "green" : event.status === "Concluído" ? "blue" : "neutral"}>{event.status}</Badge></span></div>)}{reportEvents.length === 0 && <div className="report-empty-state">Nenhum evento neste período. Escolha outra data ou série.</div>}</div></section>
  </>;
}
function SettingsPage({ onNotice, dark, setDark }: { onNotice: (message: string) => void; dark: boolean; setDark: (dark: boolean) => void }) { return <><SectionTitle eyebrow="SEU ESPAÇO" title="Configurações" subtitle="Preferências da comunidade e do sistema." action={<button className="button button-primary" onClick={() => onNotice("Configurações salvas")}><Check size={15} />Salvar alterações</button>} /><div className="settings-layout"><nav className="settings-nav"><span>GERAL</span><a className="settings-active" href="#comunidade"><Church size={15} />Comunidade</a><a href="#aparencia"><Sun size={15} />Aparência</a><a href="#presenca"><QrCode size={15} />Presenças e QR Code</a></nav><div className="settings-content"><section className="card settings-section" id="comunidade"><div className="settings-heading"><h3>Dados da comunidade</h3><p>Informações básicas do espaço.</p></div><label className="settings-label">NOME DA COMUNIDADE<input defaultValue="Cristo Alegria" /></label><label className="settings-label">EMAIL DE CONTATO<input defaultValue="contato@cristoalegria.org" /></label></section><section className="card settings-section" id="aparencia"><div className="settings-heading"><h3>Aparência</h3><p>Personalize como o PresenCA aparece para você.</p></div><div className="setting-toggle-row"><div className="setting-icon"><Sun size={17} /></div><div className="setting-toggle-copy"><strong>Tema escuro</strong><small>Reduz o brilho em ambientes escuros.</small></div><button className={`toggle ${dark ? "toggle-on" : ""}`} onClick={() => setDark(!dark)}><i /></button></div></section><section className="card settings-section" id="presenca"><div className="settings-heading"><h3>Presenças e QR Code</h3><p>Configuração de check-in.</p></div><label className="settings-label">EXPIRAÇÃO DO QR CODE<select defaultValue="5 minutos"><option>1 minuto</option><option>5 minutos</option><option>10 minutos</option><option>15 minutos</option></select></label></section></div></div></>; }

function ProfilePage({ onNotice }: { onNotice: (s: string) => void }) { const [tab, setTab] = useState("Dados pessoais"); const profileTabs: { title: string; icon: LucideIcon }[] = [{ title: "Dados pessoais", icon: UserRound }, { title: "Segurança", icon: LockKeyhole }, { title: "Preferências", icon: SlidersHorizontal }, { title: "Notificações", icon: Bell }]; return <><SectionTitle eyebrow="MINHA CONTA" title="Meu perfil" subtitle="Gerencie seus dados pessoais e preferências." action={<button className="button button-primary" onClick={() => onNotice("Perfil atualizado com sucesso")}><Check size={15} />Salvar alterações</button>} /><div className="profile-layout"><nav className="card profile-tabs">{profileTabs.map(({ title, icon: Icon }) => <button className={tab === title ? "profile-tab-active" : ""} onClick={() => setTab(title)} key={title}><Icon size={15} />{title}</button>)}</nav><div className="profile-column"><section className="card profile-card"><div className="settings-heading"><h3>{tab}</h3><p>Estas informações estão visíveis apenas para a equipe de organização.</p></div><div className="profile-photo-row"><Avatar name="Igor Felipe" size="large" /><div><strong>Sua foto de perfil</strong><small>JPG ou PNG. Máximo de 5 MB.</small></div><button className="button button-secondary" onClick={() => onNotice("Selecione uma foto de perfil")}>Alterar foto</button></div><div className="profile-form-grid"><label className="settings-label">NOME COMPLETO<input defaultValue="Igor Felipe" /></label><label className="settings-label">CARGO<input defaultValue="Administradora" /></label><label className="settings-label">EMAIL<input defaultValue="igor@cristoalegria.org" /></label><label className="settings-label">TELEFONE<input defaultValue="(11) 98123-4567" /></label><label className="settings-label">CIDADE<input defaultValue="Goiânia - GO" /></label><label className="settings-label">COMUNIDADE<input defaultValue="Cristo Alegria" /></label></div><button className="button button-secondary profile-password" onClick={() => onNotice("Uma solicitação para alterar sua senha será enviada por email")}><LockKeyhole size={14} />Alterar senha</button></section><section className="card profile-card"><div className="settings-heading"><h3>Preferências de uso</h3><p>Uma experiência do jeitinho que você gosta.</p></div><div className="setting-toggle-row"><div className="setting-icon"><Bell size={16} /></div><div className="setting-toggle-copy"><strong>Notificações por email</strong><small>Receba atualizações importantes da comunidade.</small></div><button className="toggle toggle-on" onClick={(e) => e.currentTarget.classList.toggle("toggle-on")}><i /></button></div></section><button className="button button-danger profile-logout" onClick={() => onNotice("Sessão encerrada com segurança")}><LogOut size={15} />Sair da conta</button></div></div></>; }

function QrPage({ onNotice }: { onNotice: (s: string) => void }) { const [seconds, setSeconds] = useState(248); useEffect(() => { const t = setInterval(() => setSeconds((s) => s <= 1 ? 300 : s - 1), 1000); return () => clearInterval(t); }, []); return <><SectionTitle eyebrow="CHECK-IN DIGITAL" title="QR Code de presença" subtitle="Facilite o registro de presença nos seus encontros." action={<button className="button button-secondary" onClick={() => onNotice("Selecione o QR Code para baixar")}><Download size={15} />Baixar QR Code</button>} /><div className="qr-layout"><section className="card qr-main-card"><div className="qr-top-label"><span className="live-dot" />ATIVO <i>·</i> ENCONTRO DE JOVENS</div><h2>Pronto para receber a comunidade.</h2><p>Peça para os participantes apontarem a câmera para o código abaixo.</p><div className="qr-code-frame"><QrPattern /><span className="qr-logo-center"><Church size={21} /></span></div><div className="qr-countdown"><span><Clock3 size={14} />Novo código em</span><strong>0{Math.floor(seconds / 60)}:{String(seconds % 60).padStart(2, "0")}</strong><div className="qr-timer"><i style={{ width: `${(seconds / 300) * 100}%` }} /></div></div><div className="qr-actions"><button className="button button-primary" onClick={() => { setSeconds(300); onNotice("Novo QR Code gerado"); }}><QrCode size={15} />Gerar novo QR Code</button><button className="button button-secondary" onClick={() => { navigator.clipboard?.writeText("https://presenca.org.br/checkin/encontro-jovens"); onNotice("Link do evento copiado!"); }}><Upload size={14} />Copiar link</button></div></section><div className="qr-side"><section className="card qr-event-card"><CardHead title="Evento selecionado" /><div className="qr-event-detail"><span className="qr-event-icon"><CalendarDays size={18} /></span><div><strong>Encontro de Jovens</strong><small><CalendarDays size={12} />Hoje, 10 nov · 19:30</small><small><MapPin size={12} />Salão São Francisco</small></div></div><button className="text-link" onClick={() => onNotice("Selecionar outro evento")}>Trocar evento <ChevronDown size={13} /></button></section><section className="card qr-stats"><div><span className="qr-stat-icon mint"><CheckCheck size={15} /></span><div><strong>36</strong><small>presenças registradas</small></div></div><div><span className="qr-stat-icon lavender"><Users size={15} /></span><div><strong>40</strong><small>participantes inscritos</small></div></div><div className="qr-stats-progress"><div className="progress-head"><span>Taxa de comparecimento</span><strong>90%</strong></div><div className="progress-track"><span style={{ width: "90%" }} /></div></div></section><section className="card qr-history"><CardHead title="Códigos recentes" subtitle="Histórico dos últimos QR Codes." /><div>{["Hoje, 18:02", "Hoje, 17:48", "08 nov, 19:12"].map((t, i) => <div className="qr-history-row" key={t}><span className="history-code"><QrCode size={15} /></span><span><strong>Encontro de Jovens</strong><small>{t}</small></span><Badge tone={i === 0 ? "green" : "neutral"}>{i === 0 ? "Ativo" : "Expirado"}</Badge></div>)}</div></section></div></div></>; }

function QrPattern() { return <div className="qr-pattern" aria-label="QR Code"><div className="qr-square square-a"><i /></div><div className="qr-square square-b"><i /></div><div className="qr-square square-c"><i /></div>{Array.from({ length: 119 }, (_, i) => <i key={i} style={{ opacity: ((i * 7 + 3) % 9) > 2 ? 1 : 0, gridColumn: (i * 13 + 2) % 13 + 1, gridRow: (i * 17 + 1) % 13 + 1 }} />)}</div>; }

function EmptyState({ title, description, icon: Icon }: { title: string; description: string; icon: LucideIcon }) { return <div className="empty-state"><span><Icon size={21} /></span><strong>{title}</strong><p>{description}</p></div>; }

function CommandPalette({ onClose, onGo }: { onClose: () => void; onGo: (p: Page) => void }) { const [q, setQ] = useState(""); const results = [...navigation.map((n) => ({ label: n.label, icon: n.icon, kind: "Página" })), { label: "QR Code", icon: QrCode, kind: "Ferramenta" }, { label: "Meu perfil", icon: UserRound, kind: "Conta" }].filter((r) => r.label.toLowerCase().includes(q.toLowerCase())); return <motion.div className="modal-overlay palette-overlay" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onMouseDown={(e) => e.target === e.currentTarget && onClose()}><motion.div className="command-palette" initial={{ opacity: 0, y: -12, scale: .98 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: -10 }}><div className="palette-search"><Search size={18} /><input autoFocus placeholder="Para onde vamos?" value={q} onChange={(e) => setQ(e.target.value)} /><kbd>ESC</kbd></div><div className="palette-results"><span className="nav-label">NAVEGAÇÃO</span>{results.length ? results.map((r) => { const Icon = r.icon; return <button key={r.label} onClick={() => onGo(r.label as Page)}><Icon size={16} /><span>{r.label}</span><small>{r.kind}</small><ArrowRight size={14} /></button>; }) : <p className="palette-empty">Nenhum resultado encontrado.</p>}</div><div className="palette-footer"><span><kbd>↑</kbd><kbd>↓</kbd> para navegar</span><span><kbd>↵</kbd> para selecionar</span><span><kbd>ESC</kbd> para fechar</span></div></motion.div></motion.div>; }

function MemberDrawer({ member: m, onClose }: { member: Member; onClose: () => void }) { return <motion.div className="drawer-overlay" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onMouseDown={(e) => e.target === e.currentTarget && onClose()}><motion.aside className="member-drawer" initial={{ x: 500 }} animate={{ x: 0 }} exit={{ x: 500 }} transition={{ type: "spring", damping: 30 }}><div className="drawer-head"><span className="eyebrow">PERFIL DO MEMBRO</span><div><IconButton label="Fechar painel" onClick={onClose}><X size={17} /></IconButton><IconButton label="Mais opções"><MoreHorizontal size={17} /></IconButton></div></div><div className="drawer-profile"><Avatar name={m.name} src={m.avatar} size="large" /><div><h2>{m.name}</h2><Badge tone={m.status === "Ativo" ? "green" : "neutral"} dot>{m.status}</Badge></div><button className="button button-secondary" onClick={() => {}}><Ellipsis size={15} /></button></div><div className="drawer-contact"><a href={`mailto:${m.email}`}><Mail size={14} />{m.email}</a><a href={`tel:${m.phone}`}><span className="phone-icon">⌕</span>{m.phone}</a></div><div className="drawer-tabs"><button className="drawer-tab-active">Visão geral</button><button>Presenças</button><button>Eventos</button></div><div className="drawer-body"><div className="drawer-section"><h3>Sobre</h3><div className="detail-grid"><div><small>CIDADE</small><strong>{m.city}, SP</strong></div><div><small>GRUPO</small><strong>{m.group}</strong></div><div><small>MEMBRO DESDE</small><strong>{m.since}</strong></div><div><small>STATUS</small><strong><Badge tone="green" dot>{m.status}</Badge></strong></div><div><small>TELEFONE</small><strong>{m.phone}</strong></div><div><small>EMAIL</small><strong className="detail-email">{m.email}</strong></div></div></div><div className="drawer-section last-visit-detail"><h3>Última visita</h3><div><CalendarDays size={15} /><span><strong>{m.lastVisit?.date || "Sem visitas registradas"}</strong><small>{m.lastVisit?.event || "Ainda não participou de um evento."}</small></span></div></div><div className="drawer-section"><h3>Presença na comunidade <span className="period-chip">Últimos 6 meses <ChevronDown size={11} /></span></h3><div className="member-attendance"><div><strong>{m.attendance}%</strong><small>frequência média</small></div><div className="member-bars">{[48, 68, 75, 55, 84, m.attendance].map((n, i) => <span key={i} style={{ height: `${n}%` }} />)}</div></div><div className="attendance-legend"><span><i />presente</span><span><i />ausente</span><span><i />justificado</span></div></div><div className="drawer-section"><h3>Últimas atividades</h3>{["Encontro de Jovens", "Missa da Comunidade", "Grupo de Oração"].map((e, i) => <div className="member-activity" key={e}><span className="activity-dot" /><span><strong>{e}</strong><small>{["10 nov, 2026", "07 nov, 2026", "03 nov, 2026"][i]}</small></span><Badge tone={i === 1 ? "blue" : "green"} dot>{i === 1 ? "Justificado" : "Presente"}</Badge></div>)}</div><div className="drawer-section"><h3>Observações</h3><div className="member-note"><MessageSquare size={14} /><span>Participa ativamente do grupo de jovens. Voluntário na pastoral da acolhida.</span></div></div></div><div className="drawer-footer"><button className="button button-secondary" onClick={onClose}>Fechar</button><button className="button button-primary">Editar membro</button></div></motion.aside></motion.div>; }

function FormModal({ type, recurringTemplates, onClose, onSubmit }: { type: "event" | "member" | "participant" | "organizer"; recurringTemplates: RecurringEventTemplate[]; onClose: () => void; onSubmit: (e: React.FormEvent<HTMLFormElement>, label: string) => void }) {
  const [seriesId, setSeriesId] = useState("");
  const [creatingSeries, setCreatingSeries] = useState(false);
  const [seriesValues, setSeriesValues] = useState({ name: "", type: "Encontro", weekday: "4", time: "19:30", location: "", owner: organizers[0]?.name || "", capacity: "", description: "", observations: "" });
  const [eventValues, setEventValues] = useState({ name: "", description: "", date: localDateValue(), time: "19:30", location: "", category: "Encontro", owner: organizers[0]?.name || "", capacity: "", observations: "" });
  const selectedSeries = recurringTemplates.find((item) => item.id === seriesId);
  const updateEventValue = (field: keyof typeof eventValues, value: string) => setEventValues((values) => ({ ...values, [field]: value }));
  const updateSeriesValue = (field: keyof typeof seriesValues, value: string) => setSeriesValues((values) => ({ ...values, [field]: value }));
  const selectSeries = (id: string) => {
    setSeriesId(id);
    const template = recurringTemplates.find((item) => item.id === id);
    if (!template) {
      setEventValues((values) => ({ ...values, name: "", description: "", date: localDateValue(), category: "Encontro", time: "19:30", location: "", owner: organizers[0]?.name || "", capacity: "", observations: "" }));
      return;
    }
    setEventValues((values) => ({ ...values, name: template.name, description: template.description, date: nextDateForWeekday(template.weekday), time: template.time, location: template.location, category: template.type, owner: template.owner, capacity: String(template.capacity), observations: template.observations }));
  };
  const config = { event: ["Novo evento", "Agende um encontro avulso ou escolha uma série recorrente."], member: ["Novo membro", "Adicione uma pessoa à comunidade."], participant: ["Cadastro de participante", "Conte um pouco sobre você para participar."], organizer: ["Adicionar organizador", "Convide alguém para ajudar a comunidade."] } as const;
  const [title, subtitle] = config[type];
  const label = type === "event" ? "Evento" : type === "member" ? "Membro" : type === "participant" ? "Cadastro" : "Organizador";
  return <motion.div className="modal-overlay" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
    <motion.section className="form-modal" initial={{ opacity: 0, y: 15, scale: .98 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 10 }}>
      <div className="form-modal-head"><span className="form-modal-icon">{type === "event" ? <CalendarDays size={18} /> : type === "organizer" ? <Shield size={18} /> : <UserPlus size={18} />}</span><div><h2>{type === "event" && creatingSeries ? "Novo evento recorrente" : title}</h2><p>{type === "event" && creatingSeries ? "Defina os dados fixos da nova série recorrente." : subtitle}</p></div><IconButton label="Fechar" onClick={onClose}><X size={17} /></IconButton></div>
      <form onSubmit={(e) => onSubmit(e, creatingSeries ? "Série" : label)}>
        <div className="modal-form-grid">
          {type === "event" ? (creatingSeries ? <>
            <div className="series-create-banner field-full"><span>O primeiro encontro será agendado no próximo dia escolhido.</span><button type="button" className="text-link" onClick={() => setCreatingSeries(false)}><ChevronLeft size={13} />Voltar ao evento</button></div>
            <label className="settings-label field-full">NOME DA SÉRIE<input required name="seriesName" value={seriesValues.name} placeholder="Ex.: Grupo de Oração" onChange={(e) => updateSeriesValue("name", e.target.value)} /></label>
            <label className="settings-label">CATEGORIA<select name="seriesType" value={seriesValues.type} onChange={(e) => updateSeriesValue("type", e.target.value)}><option>Encontro</option><option>Celebração</option><option>Formação</option><option>Ação social</option><option>Confraternização</option><option>Retiro</option></select></label>
            <label className="settings-label">DIA DA SEMANA<select name="weekday" value={seriesValues.weekday} onChange={(e) => updateSeriesValue("weekday", e.target.value)}>{weekdayNames.map((day, index) => <option key={day} value={index}>{day}</option>)}</select></label>
            <label className="settings-label">HORÁRIO<input required name="time" type="time" value={seriesValues.time} onChange={(e) => updateSeriesValue("time", e.target.value)} /></label>
            <label className="settings-label field-full">LOCAL<input required name="location" value={seriesValues.location} placeholder="Endereço ou local do encontro" onChange={(e) => updateSeriesValue("location", e.target.value)} /></label>
            <label className="settings-label">RESPONSÁVEL<select name="owner" value={seriesValues.owner} onChange={(e) => updateSeriesValue("owner", e.target.value)}>{organizers.map((organizer) => <option key={organizer.id}>{organizer.name}</option>)}</select></label>
            <label className="settings-label">CAPACIDADE<input name="capacity" type="number" min="1" value={seriesValues.capacity} placeholder="Sem limite" onChange={(e) => updateSeriesValue("capacity", e.target.value)} /></label>
            <label className="settings-label field-full">DESCRIÇÃO<textarea name="seriesDescription" rows={2} value={seriesValues.description} placeholder="Descrição padrão da série" onChange={(e) => updateSeriesValue("description", e.target.value)} /></label>
            <label className="settings-label field-full">OBSERVAÇÕES<input name="seriesObservations" value={seriesValues.observations} placeholder="Opcional" onChange={(e) => updateSeriesValue("observations", e.target.value)} /></label>
          </> : <>
            <div className="series-select-row field-full"><label className="settings-label">SÉRIE RECORRENTE<select value={seriesId} onChange={(e) => selectSeries(e.target.value)}><option value="">Evento avulso</option>{recurringTemplates.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><button type="button" className="button button-secondary" onClick={() => setCreatingSeries(true)}><Plus size={14} />Novo evento recorrente</button></div>
            <input type="hidden" name="seriesId" value={seriesId} />
            {selectedSeries && <div className="recurring-series-info field-full"><span className="series-info-icon"><CalendarDays size={16} /></span><div><strong>{selectedSeries.name} · toda {weekdayNames[selectedSeries.weekday]}</strong><small>Configurações padrão preenchidas. Você pode editá-las para esta ocorrência; a data deve respeitar o dia da série.</small></div></div>}
            <label className="settings-label field-full">NOME DO EVENTO<input required name="name" value={eventValues.name} placeholder="Ex.: Encontro de jovens" onChange={(e) => updateEventValue("name", e.target.value)} /></label>
            <label className="settings-label field-full">DESCRIÇÃO<textarea name="description" value={eventValues.description} placeholder="Conte um pouco sobre este evento..." rows={3} onChange={(e) => updateEventValue("description", e.target.value)} /></label>
            <label className="settings-label">DATA<input required name="date" type="date" value={eventValues.date} onChange={(e) => updateEventValue("date", e.target.value)} /></label>
            <label className="settings-label">HORÁRIO<input required name="time" type="time" value={eventValues.time} onChange={(e) => updateEventValue("time", e.target.value)} /></label>
            <label className="settings-label field-full">LOCAL<input required name="location" value={eventValues.location} placeholder="Endereço ou local do encontro" onChange={(e) => updateEventValue("location", e.target.value)} /></label>
            <label className="settings-label">CATEGORIA<select name="type" value={eventValues.category} onChange={(e) => updateEventValue("category", e.target.value)}><option>Encontro</option><option>Celebração</option><option>Formação</option><option>Ação social</option><option>Confraternização</option><option>Retiro</option></select></label>
            <label className="settings-label">RESPONSÁVEL<select name="owner" value={eventValues.owner} onChange={(e) => updateEventValue("owner", e.target.value)}>{selectedSeries && !organizers.some((organizer) => organizer.name === selectedSeries.owner) && <option>{selectedSeries.owner}</option>}{organizers.map((organizer) => <option key={organizer.id}>{organizer.name}</option>)}</select></label>
            <label className="settings-label">CAPACIDADE<input name="capacity" type="number" min="1" value={eventValues.capacity} placeholder="Sem limite" onChange={(e) => updateEventValue("capacity", e.target.value)} /></label>
            <label className="settings-label">OBSERVAÇÕES<input name="observations" value={eventValues.observations} placeholder="Opcional" onChange={(e) => updateEventValue("observations", e.target.value)} /></label>
          </>) : <>
            <label className="settings-label field-full">NOME COMPLETO<input required name="name" placeholder="Como podemos te chamar?" /></label>
            {type !== "participant" && <label className="settings-label">EMAIL<input name="email" type="email" required placeholder="email@exemplo.com" /></label>}
            <label className="settings-label">TELEFONE<input required name="phone" type="tel" placeholder="(11) 99999-9999" /></label>
            {type !== "participant" && type !== "organizer" && <><label className="settings-label">CIDADE<input name="city" placeholder="Sua cidade" /></label><label className="settings-label">POSIÇÃO<select name="position" defaultValue="Consagrado"><option>Consagrado</option><option>Aspirante</option><option>Vocacionado</option><option>Voluntário</option></select></label></>}
            {type === "participant" && <><label className="settings-label">EMAIL<input name="email" type="email" placeholder="voce@email.com" /></label><label className="settings-label field-full">CIDADE<input name="city" placeholder="Sua cidade" /></label></>}
            {type === "organizer" && <label className="settings-label field-full">PERMISSÃO<select name="permission"><option>Organizador</option><option>Administradora</option><option>Visualização</option></select></label>}
          </>}
        </div>
        <div className="form-modal-actions"><button type="button" className="button button-secondary" onClick={onClose}>Cancelar</button><button type="submit" className="button button-primary"><Check size={15} />{creatingSeries ? "Criar série e primeiro evento" : type === "participant" ? "Salvar cadastro" : `Salvar ${label.toLowerCase()}`}</button></div>
      </form>
    </motion.section>
  </motion.div>;
}
